import os, re, subprocess, zipfile, html, sys
from pathlib import Path

base = Path('/root/papers/all')
files = [p for p in base.iterdir() if p.is_file()]

keywords = {
    'LLM': [
        'large language model', 'language model', 'llm', 'transformer', 'attention', 'gpt', 'chatgpt',
        'instruction tuning', 'prompt', 'token', 'pretraining', 'fine-tuning', 'finetuning', 'rlhf',
        'alignment', 'foundation model', 'bert', 'llama', 'mistral', 'few-shot', 'in-context'
    ],
    'trapped_ion_and_qc': [
        'trapped ion', 'ion trap', 'quantum computing', 'quantum computer', 'quantum processor',
        'qubit', 'quantum gate', 'quantum circuit', 'quantum algorithm', 'quantum error correction',
        'quantum logic', 'entanglement', 'superposition', 'coherence', 'quantum simulation',
        'pauli', 'hadamard', 'cnot', 'rydberg'
    ],
    'black_hole': [
        'black hole', 'event horizon', 'schwarzschild', 'kerr', 'hawking', 'singularity',
        'accretion', 'gravitational wave', 'quasinormal', 'ringdown', 'bh merger', 'binary black hole',
        'lensing', 'sgr a', 'horizon', 'ergosphere'
    ],
    'DNA': [
        'dna', 'genome', 'genetic', 'gene', 'chromosome', 'nucleotide', 'base pair', 'double helix',
        'sequencing', 'genomics', 'crispr', 'mrna', 'rna', 'protein', 'polymerase'
    ],
    'music_history': [
        'music history', 'music', 'composer', 'symphony', 'baroque', 'classical', 'romantic',
        'jazz', 'blues', 'rock', 'hip hop', 'opera', 'musicology', 'orchestra', 'sonata', 'fugue',
        'melody', 'harmony', 'rhythm'
    ],
}

# Precompile regex for word boundaries for single words; phrases use simple count
single_word_re = {k: re.compile(r'\b' + re.escape(k) + r'\b') for cat in keywords.values() for k in cat if ' ' not in k}


def extract_text(path: Path, max_chars=600000):
    ext = path.suffix.lower()
    try:
        if ext == '.pdf':
            # pdftotext to stdout
            result = subprocess.run(['pdftotext', '-q', str(path), '-'], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, check=False)
            text = result.stdout.decode('utf-8', errors='ignore')
        elif ext == '.docx':
            with zipfile.ZipFile(path) as z:
                xml = z.read('word/document.xml').decode('utf-8', errors='ignore')
            text = re.sub(r'<[^>]+>', ' ', xml)
            text = html.unescape(text)
        elif ext == '.pptx':
            texts = []
            with zipfile.ZipFile(path) as z:
                for name in z.namelist():
                    if name.startswith('ppt/slides/slide') and name.endswith('.xml'):
                        xml = z.read(name).decode('utf-8', errors='ignore')
                        texts.append(re.sub(r'<[^>]+>', ' ', xml))
                    elif name.startswith('ppt/notesSlides/notesSlide') and name.endswith('.xml'):
                        xml = z.read(name).decode('utf-8', errors='ignore')
                        texts.append(re.sub(r'<[^>]+>', ' ', xml))
            text = ' '.join(texts)
            text = html.unescape(text)
        else:
            # Fallback: try strings from binary
            result = subprocess.run(['strings', '-n', '4', str(path)], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, check=False)
            text = result.stdout.decode('utf-8', errors='ignore')
    except Exception:
        text = ''
    if len(text) > max_chars:
        text = text[:max_chars]
    return text.lower()


def score_text(text):
    scores = {k: 0 for k in keywords}
    for cat, keys in keywords.items():
        for k in keys:
            if ' ' in k:
                scores[cat] += text.count(k)
            else:
                scores[cat] += len(single_word_re[k].findall(text))
    return scores


def classify(text):
    scores = score_text(text)
    # prefer more specific phrases by small bonus
    if 'black hole' in text:
        scores['black_hole'] += 5
    if 'trapped ion' in text or 'ion trap' in text:
        scores['trapped_ion_and_qc'] += 5
    if 'language model' in text or 'large language model' in text:
        scores['LLM'] += 5
    if re.search(r'\bdna\b', text):
        scores['DNA'] += 5
    if 'music history' in text:
        scores['music_history'] += 5
    # pick max, fallback to music_history if all zero
    best = max(scores.items(), key=lambda kv: (kv[1], kv[0]))
    if best[1] == 0:
        return 'music_history', scores
    return best[0], scores

rows = []
for p in sorted(files):
    text = extract_text(p)
    cat, scores = classify(text)
    rows.append((p.name, cat, scores))

# Print summary counts
from collections import Counter
cnt = Counter([r[1] for r in rows])
print('Counts:', dict(cnt))

# Print top 5 ambiguous (low score)
amb = sorted(rows, key=lambda r: max(r[2].values()))[:10]
print('Lowest scores:')
for name, cat, scores in amb:
    print(name, cat, scores)

# Save csv for manual inspection
import csv
with open('/root/papers/classification.csv', 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['file', 'category', 'scores'])
    for name, cat, scores in rows:
        w.writerow([name, cat, scores])

